import type { EarningSource } from '~/client';

export const earningSourceLabel: Record<EarningSource, string> = {
  manual: 'Manual',
  system: 'System',
};

export function getEarningSourceLabel(source: EarningSource): string {
  return earningSourceLabel[source] ?? snakeCaseToCapitalizedCase(source);
}

export const earningSources: SelectItem<EarningSource>[] = Object.entries(earningSourceLabel).map(([value, name]) => ({
  value: value as EarningSource,
  name,
}));
