import type {
  EarningListItemForCanvasser,
  EarningListItemForManager,
  EarningListItemForAdmin,
  EarningDetailsForCanvasser,
  EarningDetailsForAdmin,
  EarningDetailsForManager,
} from '~/client';

export const isEarningListItemForCanvasser = (
  item: EarningListItemForCanvasser | EarningListItemForManager | EarningListItemForAdmin
): item is EarningListItemForCanvasser => {
  return !isEarningListItemForAdminManager(item);
};

export const isEarningListItemForAdminManager = (
  item: EarningListItemForCanvasser | EarningListItemForManager | EarningListItemForAdmin
): item is EarningListItemForAdmin | EarningListItemForManager => {
  return 'review_deadline_timestamp' in item;
};

export const isEarningListForCanvasser = (
  list: (EarningListItemForCanvasser | EarningListItemForManager | EarningListItemForAdmin)[]
): list is EarningListItemForCanvasser[] => {
  return list.every(isEarningListItemForCanvasser);
};

export const isEarningListForAdminManager = (
  list: (EarningListItemForCanvasser | EarningListItemForManager | EarningListItemForAdmin)[]
): list is (EarningListItemForAdmin | EarningListItemForManager)[] => {
  return list.every(isEarningListItemForAdminManager);
};

export const isEarningDetailsForAdminManager = (
  details: EarningDetailsForCanvasser | EarningDetailsForManager | EarningDetailsForAdmin
): details is EarningDetailsForAdmin | EarningDetailsForManager => {
  return 'canvasser' in details;
};

export const isEarningDetailsForCanvasser = (
  details: EarningDetailsForCanvasser | EarningDetailsForManager | EarningDetailsForAdmin
): details is EarningDetailsForCanvasser => {
  return !isEarningDetailsForAdminManager(details);
};
